/* Dark Message Mode */

#darkReaderToggle {
  display: none;

  & input {
    margin-block: 0;
  }
}

#headerShowDarkToggle {
  display: none;
}

/* stylelint-disable-next-line media-query-no-invalid */
@media (prefers-color-scheme: dark) and -moz-pref("mail.dark-reader.show-toggle") {
  #darkReaderToggle {
    display: initial;

    @media (prefers-contrast) {
      display: none;
    }
  }
}
